def _unpack():
    n = 0
    for rel, (h, data) in FILES.items():
        raw = zlib.decompress(base64.b64decode(data))
        if hashlib.sha256(raw).hexdigest() != h:
            raise SystemExit(f"✗ 粘贴内容损坏或被截断: {rel} —— 请重新完整复制整段代码")
        if Path(rel).is_absolute() or ".." in Path(rel).parts:
            raise SystemExit("unsafe embedded asset path")
        p = ROOT / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(raw)
        n += 1
    print(f"✓ 已写入 {n} 个文件 → {ROOT}")


_unpack()

if os.environ.get("QTTS_UNPACK_ONLY") == "1":
    print("仅解包完成；未安装依赖、读取Secrets或启动服务。")
    raise SystemExit(0)

# Kaggle Secrets → 环境变量(子进程继承)
try:
    from kaggle_secrets import UserSecretsClient
    _us = UserSecretsClient()
    for _k in ("DEEPSEEK_API_KEY", "HF_TOKEN", "KAGGLE_USERNAME", "KAGGLE_KEY", "QTTS_ACCESS_TOKEN"):
        try:
            os.environ[_k] = _us.get_secret(_k)
            print(f"✓ secret {_k} 已加载")
        except Exception:
            pass
except Exception:
    pass

os.environ.setdefault("QTTS_STATE", str(ROOT / "state"))
os.environ.setdefault("PYTHONUNBUFFERED", "1")

_p = subprocess.Popen([sys.executable, str(ROOT / "py" / "bootstrap.py")], stdout=subprocess.PIPE,
                      stderr=subprocess.STDOUT, text=True, bufsize=1, env=os.environ.copy())
for _line in _p.stdout:
    print(_line.rstrip(), flush=True)
_rc = _p.wait()
print("\n" + ("✓ 启动完成: 打开上面的 URL。自检: !python %s/tools/selftest.py --quality" % ROOT if _rc == 0
              else f"✗ 启动失败(exit {_rc}) —— 把上面最后 40 行输出发给我"))

# Propagate bootstrap failure instead of merely printing it.
raise SystemExit(_rc)
